scan_linter_check.script:
(function(engine) {
    var context = new global.EcsContext(engine.current);
    if (!engine.rootNode || context.table !== 'sys_script_include' || !context.flag('client_callable')) {
        return;
    }
    var hits = new global.EcsSecurity(new global.EcsAst(engine.rootNode)).aclBypassingRecords();
    var report = new global.EcsReport(engine, {
        ruleId: 'SEC-003',
        title: 'Client-callable Script Include queries without ACLs',
        recommendation: 'Use GlideRecordSecure in client-callable Script Includes so ACLs are enforced for the ' +
            'calling user. If GlideRecord is required, check access explicitly (canRead/canWrite) before returning ' +
            'or changing data, and validate every sysparm parameter.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
